'use client';import{useEffect,useState}from'react';import{Heart}from'lucide-react';import Link from'next/link';import PromptCard from'./PromptCard';import{promptItems}from'@/lib/prompts';export default function SavedClient(){const[ids,setIds]=useState<string[]>([]);useEffect(()=>setIds(JSON.parse(localStorage.getItem('ps-favorites')||'[]')),[]);const list=ids.map(id=>promptItems.find(p=>p.id===id)).filter(Boolean);return <section className="library">{list.length?<><div className="savedHead"><span>{list.length} SAVED</span><button onClick={()=>{localStorage.removeItem('ps-favorites');setIds([])}}>Clear all</button></div><div className="galleryGrid">{list.map((p:any)=><PromptCard p={p} key={p.id}/>)}</div></>:<div className="savedEmpty"><Heart/><h2>No saved prompts yet.</h2><p>Open any prompt and tap Save prompt.</p><Link className="blackBtn" href="/prompts">Explore gallery</Link></div>}</section>}
